36	impl JoinSelectBuilder for LateralJoinSelectBuilder {
37	    /// Builds a SELECT statement for the given query arguments and selected fields.
38	    ///
39	    /// ```sql
40	    /// SELECT
41	    ///   id,
42	    ///   name
43	    /// FROM "User"
44	    /// LEFT JOIN LATERAL (
45	    ///   SELECT JSON_OBJECT(<...>) FROM "Post" WHERE "Post"."authorId" = "User"."id
46	    /// ) as "post" ON TRUE
47	    /// ```
48	    fn build(&mut self, args: QueryArguments, selected_fields: &FieldSelection, ctx: &Context<'_>) -> Select<'static> {
49	        let (select, parent_alias) = self.build_default_select(&args, ctx);
50	        let select = self.with_relations(
51	            select,
52	            selected_fields.relations(),
53	            selected_fields.virtuals(),
54	            parent_alias,
55	            ctx,
56	        );
57	        let select = self.with_virtual_selections(select, selected_fields.virtuals(), parent_alias, ctx);
58	
59	        // Build selection as the last step utilizing the information we collected in
60	        // `with_relations` and `with_virtual_selections`.
61	        self.with_selection(select, selected_fields, parent_alias, ctx)
62	    }
63	
64	    fn build_selection<'a>(
65	        &mut self,
66	        select: Select<'a>,
67	        field: &SelectedField,
68	        parent_alias: Alias,
69	        ctx: &Context<'_>,
70	    ) -> Select<'a> {
71	        match field {
72	            SelectedField::Scalar(sf) => select.column(
73	                sf.as_column(ctx)
74	                    .table(parent_alias.to_table_string())
75	                    .set_is_selected(true),
76	            ),
77	            SelectedField::Relation(rs) => {
78	                let table_name = match rs.field.relation().is_many_to_many() {
79	                    true => m2m_join_alias_name(&rs.field),
80	                    false => join_alias_name(&rs.field),
81	                };
82	
83	                select.value(Column::from((table_name, JSON_AGG_IDENT)).alias(rs.field.name().to_owned()))
84	            }
85	            _ => select,
86	        }
87	    }
88	
89	    fn add_to_one_relation<'a>(
90	        &mut self,
91	        select: Select<'a>,
92	        rs: &RelationSelection,
93	        parent_alias: Alias,
94	        ctx: &Context<'_>,
95	    ) -> Select<'a> {
96	        let (subselect, child_alias) = self.build_to_one_select(rs, parent_alias, ctx);
97	
98	        let subselect = self.with_relations(subselect, rs.relations(), rs.virtuals(), child_alias, ctx);
99	        let subselect = self.with_virtual_selections(subselect, rs.virtuals(), child_alias, ctx);
100	
101	        // Build the JSON object using the information we collected before in `with_relations` and
102	        // `with_virtual_selections`.
103	        let subselect = subselect.value(self.build_json_obj_fn(rs, child_alias, ctx).alias(JSON_AGG_IDENT));
104	
105	        let join_table = Table::from(subselect).alias(join_alias_name(&rs.field));
106	
107	        // LEFT JOIN LATERAL ( <join_table> ) AS <relation name> ON TRUE
108	        select.left_join(join_table.on(ConditionTree::single(true.raw())).lateral())
109	    }
110	
111	    fn add_to_many_relation<'a, 'b>(
112	        &mut self,
113	        select: Select<'a>,
114	        rs: &RelationSelection,
115	        parent_virtuals: impl Iterator<Item = &'b VirtualSelection>,
116	        parent_alias: Alias,
117	        ctx: &Context<'_>,
118	    ) -> Select<'a> {
119	        let join_table_alias = join_alias_name(&rs.field);
120	        let mut to_many_select = self.build_to_many_select(rs, parent_alias, ctx);
121	
122	        if let Some(vs) = self.find_compatible_virtual_for_relation(rs, parent_virtuals) {
123	            self.visited_virtuals.insert(vs.into(), join_table_alias.clone());
124	            to_many_select = to_many_select.value(build_inline_virtual_selection(vs));
125	        }
126	
127	        let join_table = Table::from(to_many_select).alias(join_table_alias);
128	
129	        // LEFT JOIN LATERAL ( <join_table> ) AS <relation name> ON TRUE
130	        select.left_join(join_table.on(ConditionTree::single(true.raw())).lateral())
131	    }
132	
133	    fn add_many_to_many_relation<'a, 'b>(
134	        &mut self,
135	        select: Select<'a>,
136	        rs: &RelationSelection,
137	        parent_virtuals: impl Iterator<Item = &'b VirtualSelection>,
138	        parent_alias: Alias,
139	        ctx: &Context<'_>,
140	    ) -> Select<'a> {
141	        let m2m_join = self.build_m2m_join(rs, parent_virtuals, parent_alias, ctx);
142	
143	        select.left_join(m2m_join)
144	    }
