146	    fn add_virtual_selection<'a>(
147	        &mut self,
148	        select: Select<'a>,
149	        vs: &VirtualSelection,
150	        parent_alias: Alias,
151	        ctx: &Context<'_>,
152	    ) -> Select<'a> {
153	        let alias = self.next_alias();
154	        let relation_count_select = self.build_virtual_select(vs, parent_alias, ctx);
155	        let table = Table::from(relation_count_select).alias(alias.to_table_string());
156	
157	        self.visited_virtuals.insert(vs.into(), alias.to_table_string());
158	
159	        select.left_join_lateral(table.on(ConditionTree::single(true.raw())))
160	    }
